async function rawCall(instance,body,args){const result=await instance.browser.executeAsync(new Function("args","done",`import("/src/app/mockAdapter.ts").then(async({mockAdapter})=>{try{const out=await (async()=>{${body}})();done({ok:true,out});}catch(error){done({ok:false,error:String(error instanceof Error?error.message:error)});}}).catch((error)=>done({ok:false,error:String(error?.stack??error)}));`),args??{});assert.equal(result.ok,true,`${instance.label}: ${result.error}`);return result.out;}
async function tomState(instance){const result=await instance.browser.executeAsync((done)=>{import("/src/app/mockAdapter.ts").then(async({mockAdapter})=>{const s=await mockAdapter.getSnapshot();const cs=s.campaignSessionSystems;done({role:s.session.role,connectionState:s.connectionState,mode:s.sessionMode,round:s.scene.round??null,currentActorId:s.scene.currentActorId,activeCharacterId:s.activeCharacter.id,hp:s.activeCharacter.hp,maxHp:s.activeCharacter.maxHp,slots:(s.scene.spellcastingByActor?.[s.activeCharacter.id]?.slots??[]).map((l)=>({level:l.level,current:l.current,max:l.max})),sceneConditions:[...(s.scene.sceneConditions??[])],groups:Object.values(s.scene.groups??{}).map((g)=>({id:g.id,label:g.label,members:[...(g.memberIds??[])].sort()})),pendingWithdrawal:s.scene.pendingWithdrawal?{actorId:s.scene.pendingWithdrawal.actorId,candidates:s.scene.pendingWithdrawal.candidates.map((c)=>c.reactorId)}:null,entities:s.scene.entities.map((e)=>({id:e.id,name:e.name,kind:e.kind,side:e.side,hp:e.hp,maxHp:e.maxHp,ac:e.ac,initiative:e.initiative??null,status:[...(e.status??[])].sort(),engaged:[...(e.engagedWithIds??[])].sort(),movement:e.movementDeclaration?.kind??null,groupId:e.groupId??null})).sort((a,b)=>a.id<b.id?-1:1),campaign:cs?{id:cs.campaignId,name:cs.campaignName,note:cs.calendar.currentNote??null,calendarEnabled:cs.calendar.enabled,absoluteMinute:cs.calendar.absoluteMinute,rationsEnabled:cs.rations.enabled,rations:cs.rations.balance??null,roster:cs.roster.map((m)=>({id:m.rosterMemberId,label:m.label,characterId:m.characterId??null,xp:m.advancement?.xp??0,credits:m.advancement?.levelUpCredits??0}))}:null,compatibility:s.session.compatibility,compatibilityMessage:s.session.compatibilityMessage??null,longRestPrompts:(s.connectedLongRest?.ownerPrompts??[]).map((p)=>({transactionId:p.offer.transactionId,phase:p.phase,hpBefore:p.hp.before,hpAfter:p.hp.after,error:p.error??null})),activity:s.activity.slice(0,60).map((e)=>({id:e.id,actor:e.actor,title:e.title,summary:e.summary,stateChanges:e.stateChanges})),resolution:s.resolution?{id:s.resolution.id,stage:s.resolution.stage,actorId:s.resolution.actorId,actionName:s.resolution.actionName,dice:s.resolution.authoritativeDice??[],compact:s.resolution.compact,finalOutcome:s.resolution.finalOutcome,saves:(s.resolution.saveResults??[]).map((x)=>({targetName:x.targetName,total:x.total,dc:x.dc,outcome:x.outcome}))}:null});}).catch((error)=>done({error:String(error?.stack??error)}));});assert.ok(!result.error,`${instance.label}: ${result.error}`);return result;}
async function waitTom(instance,predicate,description,timeout=20_000){let last=null;await instance.browser.waitUntil(async()=>{last=await tomState(instance);return predicate(last);},{timeout,interval:200,timeoutMsg:`${instance.label} did not reach ${description}; last=${JSON.stringify({mode:last?.mode,current:last?.currentActorId,conditions:last?.sceneConditions,groups:last?.groups,pending:last?.pendingWithdrawal,campaign:last?.campaign,prompts:last?.longRestPrompts,compat:last?.compatibilityMessage,entities:last?.entities?.map((e)=>`${e.name}:${e.hp}${e.engaged.length?"⚔"+e.engaged.length:""}${e.status.length?"["+e.status.join(",")+"]":""}`),activity:last?.activity?.slice(0,3).map((e)=>e.title)})}`});return last;}
function scenePublic(state){return state.entities.map((e)=>({id:e.id,name:e.name,side:e.side,hp:e.hp,maxHp:e.maxHp,initiative:e.initiative,status:e.status,engaged:e.engaged,groupId:e.groupId}));}
async function expectTomParity(peers,label){const host=await tomState(peers[0]);const expected=JSON.stringify({scene:scenePublic(host),conditions:host.sceneConditions,groups:host.groups});for(const p of peers.slice(1)){const s=await waitTom(p,(x)=>JSON.stringify({scene:scenePublic(x),conditions:x.sceneConditions,groups:x.groups})===expected,`${label}: scene parity with the Host`);assert.equal(s.mode,host.mode,`${label}: ${p.label} mode diverges`);if(host.mode==="initiative")assert.equal(s.currentActorId,host.currentActorId,`${label}: ${p.label} current actor diverges`);}return host;}
async function createNamedCampaign(host,name){await click(host.browser,navButton("캠페인"),"캠페인 메뉴");const body=await host.browser.$("body").getText();await click(host.browser,exactButton(body.includes("아직 캠페인이 없습니다.")?"새 캠페인 만들기":"새 캠페인"),"새 캠페인");await replaceValue(host.browser,labelControl("캠페인 이름"),name,"캠페인 이름");await click(host.browser,exactButton("캠페인 만들기"),"캠페인 만들기 제출");await waitForText(host.browser,name);return rawCall(host,`const s=await mockAdapter.getSnapshot();const c=(s.campaigns??[]).find((x)=>x.name===args.name);if(!c)throw new Error("campaign not found: "+args.name);return c.campaignId;`,{name});}
async function addSrdMonstersViaUi(host,query,namePrefix,count){const pane=await hostEncounterPane(host);await setReactNumberInput(host.browser,`${pane}//input[@aria-label='추가할 마리 수']`,count);await replaceValue(host.browser,`${pane}//input[@aria-label='SRD 몬스터 검색']`,query,"SRD 몬스터 검색");await click(host.browser,`${pane}//div[contains(@class,'session-dm-monster-results')]//button[.//strong[starts-with(normalize-space(.),${JSON.stringify(namePrefix)})]]`,`SRD 몬스터 ${namePrefix} ×${count}`);const state=await waitTom(host,(s)=>s.entities.filter((e)=>e.kind!=="character"&&e.name.startsWith(namePrefix)).length>=count,`${count}× ${namePrefix} in the Host scene`);return state.entities.filter((e)=>e.kind!=="character"&&e.name.startsWith(namePrefix)).map((e)=>e.id);}
async function toggleSceneCondition(host,label){const pane=await hostEncounterPane(host);await click(host.browser,`${pane}//section[@aria-label='장면 조건']//button[normalize-space(.)=${JSON.stringify(label)}]`,`장면 조건 ${label}`);}
async function hostAttack(host,{actorId,targetId,queued,match}){const out=await hostCall(host,`await mockAdapter.selectDmActor(args.actorId);if(args.queued)await mockAdapter.setQueuedD20(args.queued);const s=await mockAdapter.getSnapshot();const list=s.scene.actionsByActor[args.actorId]??[];const re=new RegExp(args.match);const action=list.find((a)=>a.resolutionKind==="attack"&&a.available&&re.test(a.name)&&(a.eligibleTargetIds??[]).includes(args.targetId))??list.find((a)=>a.resolutionKind==="attack"&&re.test(a.name));if(!action)throw new Error("no attack matching "+args.match+" for "+args.actorId+"; have "+list.map((a)=>a.name+(a.available?"":"(x)")).join("|"));let snapshot=await mockAdapter.resolveAction(action.id,[args.targetId]);for(let step=0;step<12&&snapshot.resolution&&snapshot.resolution.stage!=="complete"&&snapshot.resolution.canAdvance;step+=1)snapshot=await mockAdapter.advanceResolution();snapshot=await mockAdapter.getSnapshot();return {actionName:action.name,resolutionId:snapshot.resolution?.id??null,stage:snapshot.resolution?.stage??null,compact:snapshot.resolution?.compact??null,dice:snapshot.resolution?.authoritativeDice??[]};`,{actorId,targetId,queued,match});assert.ok(out.resolutionId,`Host attack produced no resolution: ${JSON.stringify(out)}`);seenResolutionIds.add(out.resolutionId);return out;}
// A controlled <input type=number>: webdriverio's clear+type fights React's re-render, so set the value through the native setter and fire an input event.
async function setReactNumberInput(browser,xpath,value){const ok=await browser.execute((xpath,value)=>{const input=document.evaluate(xpath,document,null,XPathResult.FIRST_ORDERED_NODE_TYPE,null).singleNodeValue;if(!input)return false;const setter=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,"value").set;setter.call(input,String(value));input.dispatchEvent(new Event("input",{bubbles:true}));return input.value===String(value);},xpath,value);assert.equal(ok,true,`number input ${xpath} did not take ${value}`);}
// An open ability check stops at effect-preview ("DM 공개 DC 대기") until the DM sets the DC in the result card; the runner plays the DM: 공개 DC → 판정 확정.
async function playerCheck(peer,actorId,actionId,queued,host,dc){await hostCall(host,`await mockAdapter.setQueuedD20(args.queued);`,{queued});const action=await findAction(peer,actorId,(a)=>a.id===actionId,actionId);const started=await clientAct(peer,action.id,[]);assert.equal(started.ok,true,started.error);const hostRes=await waitHostResolutionFor(host,actorId);let done=await hostAdvanceToComplete(host,hostRes.resolution.id);let dcPath="none";if(done.resolution&&done.resolution.id===hostRes.resolution.id&&done.resolution.stage!=="complete"){const form="//form[@aria-label='능력 판정 난이도 설정']";await host.browser.$(form).waitForDisplayed({timeout:10_000,timeoutMsg:`DC form did not open for ${actionId}`});await setReactNumberInput(host.browser,`${form}//label[.//span[normalize-space(.)='공개 DC']]//input`,dc);await click(host.browser,`${form}//button[normalize-space(.)='판정 확정']`,"판정 확정");dcPath="ui";done=await hostAdvanceToComplete(host,hostRes.resolution.id);}assert.equal(done.resolution?.stage,"complete",JSON.stringify(done.resolution));return {resolutionId:done.resolution.id,name:action.name,dice:done.resolution.dice,compact:done.resolution.compact,finalOutcome:done.resolution.finalOutcome,dc,dcPath};}
async function playerAct(peer,actorId,pick,targets,queued,host,label){if(queued)await hostCall(host,`await mockAdapter.setQueuedD20(args.queued);`,{queued});const action=await findAction(peer,actorId,pick,label);const started=await clientAct(peer,action.id,targets);assert.equal(started.ok,true,`${label}: ${started.error}`);const hostRes=await waitHostResolutionFor(host,actorId);const done=await hostAdvanceToComplete(host,hostRes.resolution.id);assert.equal(done.resolution?.stage,"complete",`${label}: ${JSON.stringify(done.resolution)}`);return {resolutionId:done.resolution.id,name:action.name,dice:done.resolution.dice,compact:done.resolution.compact,finalOutcome:done.resolution.finalOutcome,saves:done.resolution.saves};}
function ent(state,id){return state.entities.find((e)=>e.id===id);}
// The DM tools disable 이니셔티브 시작/종료 while a result card is open; the DM closes the card first (닫기), like at the table.
async function closeResultCard(host){const close=await host.browser.$("//button[normalize-space(.)='닫기']");if(await close.isExisting()&&await close.isDisplayed().catch(()=>false)){await close.click();}else{await hostCall(host,`if((await mockAdapter.getSnapshot()).resolution)await mockAdapter.dismissResolution();`);}await waitTom(host,(x)=>!x.resolution,"no open result card",10_000);}
async function clickInitiative(host,label){await closeResultCard(host);const pane=await hostEncounterPane(host);await click(host.browser,`${pane}//button[normalize-space(.)=${JSON.stringify(label)}]`,label);}
// The chrome tabs (시간·식량·휴식) render as span+strong, so they are matched by their span label.
async function openTab(instance,label){const active=await instance.browser.$(`//button[contains(@class,'active')][.//span[normalize-space(.)=${JSON.stringify(label)}]]`);if(await active.isExisting())return;await click(instance.browser,`//button[.//span[normalize-space(.)=${JSON.stringify(label)}]]`,`${instance.label} ${label} 탭`);await sleep(300);}


// ---------------------------------------------------------------------------------------------
// TOM2 — "무너진 종탑": every play kind and the deliberately wrong plays in one theater-of-mind session on real
// Windows H+P1+P2. Scenario text and the VTT mapping: docs/design/scenarios/fallen-bell-tower.md (V1.6 S1-04).
// ---------------------------------------------------------------------------------------------
function korean(text){return /[가-힣]/.test(String(text??""));}
async function noticeText(instance){return instance.browser.execute(()=>document.querySelector(".session-refusal-notice")?.textContent??null).catch(()=>null);}
async function waitRefusal(instance,predicate,label,timeout=20_000){let last=null;try{await instance.browser.waitUntil(async()=>{last=await peerState(instance);return Boolean(last.refusal&&predicate(last.refusal));},{timeout,interval:150,timeoutMsg:"refusal wait timed out"});}catch(error){throw new Error(`${instance.label} did not see the refusal ${label}; refusal=${JSON.stringify(last?.refusal)} resolution=${JSON.stringify(last?.resolution&&{id:last.resolution.id,stage:last.resolution.stage,actionName:last.resolution.actionName})} activity=${JSON.stringify(last?.activity?.slice(0,3).map((e)=>e.title))} msg=${last?.compatibilityMessage} (${error instanceof Error?error.message:error})`);}return last.refusal;}
async function expectRefused(peer,host,actorId,pick,targets,label,expected={}){
  const action=await findAction(peer,actorId,pick,label);
  if(expected.projectedUnavailable!==undefined)assert.equal(action.available,!expected.projectedUnavailable,`${label}: the player's projected tile availability (${action.disabledReason??"—"})`);
  const peerBefore=await peerState(peer);const hostBefore=await peerState(host);
  const started=await clientAct(peer,action.id,targets);assert.equal(started.ok,true,`${label}: ${started.error}`);
  const refusal=await waitRefusal(peer,(r)=>r.id!==(peerBefore.refusal?.id??0),label);
  assert.equal(refusal.origin,"host",`${label}: a Host refusal`);
  assert.ok(korean(refusal.message),`${label}: the refusal must read in Korean; got ${JSON.stringify(refusal)}`);
  if(expected.code)assert.equal(refusal.code,expected.code,`${label}: refusal code (${refusal.message})`);
  if(expected.message)assert.equal(refusal.message,expected.message,`${label}: refusal message`);
  if(expected.messagePattern)assert.match(refusal.message,expected.messagePattern,`${label}: refusal message`);
  const notice=await noticeText(peer);assert.ok(notice&&notice.includes(refusal.message),`${label}: the dock notice shows the refusal; notice=${JSON.stringify(notice)}`);
  const hostRefusal=await waitRefusal(host,(r)=>r.origin==="remote"&&r.actorId===actorId&&r.id!==(hostBefore.refusal?.id??0),`${label} (DM side)`);
  assert.equal(hostRefusal.message,refusal.message,`${label}: the DM sees the same reason`);
  const hostAfter=await peerState(host);
  assert.equal(hostAfter.activity[0]?.id??null,hostBefore.activity[0]?.id??null,`${label}: nothing was committed on the Host`);
  assert.equal(hostAfter.pendingRemote,false,`${label}: no remote action left pending`);
  return {action:action.name,code:refusal.code,message:refusal.message};
}
async function waitProjected(peer,actorId,pick,predicate,label,timeout=15_000){let last=null;try{await peer.browser.waitUntil(async()=>{const list=await actions(peer,actorId);if(list.error)return false;last=list.find(pick)??null;return Boolean(last&&predicate(last));},{timeout,interval:200,timeoutMsg:"projection wait timed out"});}catch(error){throw new Error(`${peer.label} projection did not reach ${label}; last=${JSON.stringify(last)} (${error instanceof Error?error.message:error})`);}return last;}
async function hostConcentration(host){return peerCall(host,`const {snapshotAdapterTurnRuntimeState}=await import("/src/app/turnRuntimeSessionRegistry.ts");const s=await mockAdapter.getSnapshot();const st=snapshotAdapterTurnRuntimeState(mockAdapter,s.scene);return st?{concentration:st.concentration,effects:st.effects.map((e)=>({sourceId:e.sourceId,targetId:e.targetId,tags:e.tags??[]}))}:null;`);}
async function hostAdvanceUntil(host,resolutionId,predicate,timeout=20_000){const started=Date.now();let last=null;while(Date.now()-started<timeout){last=await peerState(host);if(!last.resolution||last.resolution.id!==resolutionId)return last;if(predicate(last.resolution))return last;if(last.resolution.canAdvance)await hostCall(host,`await mockAdapter.advanceResolution();`);else await sleep(250);}return last;}
async function readyConfigurations(instance){return peerCall(instance,`const {readyActionConfigurationsFor}=await import("/src/app/standardActionReadyState.ts");return readyActionConfigurationsFor(mockAdapter);`);}
async function waitCursor(instance,cursor,timeout=20_000){let last=null;await instance.browser.waitUntil(async()=>{last=await peerState(instance);return (last.cursor??0)>=cursor;},{timeout,interval:200,timeoutMsg:`${instance.label} did not reach cursor ${cursor}`});return last;}
async function waitEntity(instance,entityId,predicate,label,timeout=20_000){let last=null;try{await instance.browser.waitUntil(async()=>{last=await tomState(instance);const e=ent(last,entityId);return Boolean(e&&predicate(e));},{timeout,interval:200,timeoutMsg:"entity wait timed out"});}catch(error){throw new Error(`${instance.label} did not see ${label}; entity=${JSON.stringify(last&&ent(last,entityId))}`);}return ent(last,entityId);}
async function everyPeerEntity(peers,entityId,predicate,label){const out={};for(const p of peers){const e=await waitEntity(p,entityId,predicate,label);out[p.label]={hp:e.hp,ac:e.ac,status:e.status};}return out;}
const isAttack=(name)=>(a)=>a.resolutionKind==="attack"&&new RegExp(name).test(a.name);
async function hostSlots(host,actorId){return hostCall(host,`const s=await mockAdapter.getSnapshot();return (s.scene.spellcastingByActor?.[args.id]?.slots??[]).map((l)=>({level:l.level,current:l.current,max:l.max}));`,{id:actorId});}

async function runScenario(){
  assert.equal(process.platform,"win32","TOM2 Tauri acceptance is Windows-only");assert.ok(existsSync(binary),`Tauri E2E binary was not found: ${binary}`);
  await rm(runRoot,{recursive:true,force:true});await mkdir(artifactRoot,{recursive:true});await ensureVite();
  const sessionPort=await reservePort();
  const host=await launchInstance("TOM2 Host",path.join(runRoot,"host","data"),await reservePort());const p1=await launchInstance("TOM2 P1",path.join(runRoot,"p1","data"),await reservePort());const p2=await launchInstance("TOM2 P2",path.join(runRoot,"p2","data"),await reservePort());
  const peers=[host,p1,p2];const beats={};const record=(id,data)=>{beats[id]={status:"PASS",...data};log(`${id} PASS`);};
  const CLERIC={className:"클레릭",spellTiles:{"choice:class.spells.cantrips":["신성한 불길","인도","빛"],"choice:class.spells.prepared":["신앙의 방패","상처 치료","유도 화살","치유의 단어"]},choiceCards:{"choice:class.divine-order":"수호자","choice:class.loadout.0":"부적"}};
  const sera=await createDistinctPlayerCharacter(p1,"세라",CLERIC);await stowShield(p1);
  const kael=await createDistinctPlayerCharacter(p2,"카엘");
  const campaignId=await createNamedCampaign(host,"무너진 종탑");
  await openHostSession(host,sessionPort);await joinClientSession(p1,sessionPort);await joinClientSession(p2,sessionPort);
  await waitTom(host,(s)=>s.entities.filter((e)=>e.kind==="character").length===2,"both players in the scene");
  await evidenceAll(peers,"tom2-00-table");
  try{
    // 장면 1 · 종탑 아래 마을 — 물약 지급, 신앙의 방패(집중), 도움, 대상 초과 거부.
    await rawCall(host,`const template={definitionId:"dnd.srd521.item.gear.potion-of-healing",name:"치유 물약",nameEn:"Potion of Healing",kind:"consumable",passiveEffects:[],grantedActionIds:["action.healing-potion"],provenance:["무너진 종탑 · 약초상"]};await mockAdapter.upsertCampaignDmLibraryEntry(args.id,{entryId:"tower.potion",kind:"custom-item",label:"치유 물약",definitionId:template.definitionId,favorite:false,tags:["TOM2"],itemTemplate:template});await mockAdapter.grantCampaignDmLibraryItem(args.id,"tower.potion",{kind:"character",actorId:args.actorId},1);`,{id:campaignId,actorId:kael.id});
    const potionQuantity=(state)=>(state.items??[]).filter((i)=>/potion-of-healing/.test(i.definitionId)).reduce((sum,i)=>sum+i.quantity,0);
    await p2.browser.waitUntil(async()=>potionQuantity(await peerState(p2))>=1,{timeout:20_000,timeoutMsg:"카엘 did not receive the potion"});
    await host.browser.waitUntil(async()=>((await paritySnapshot(host,kael.id)).inventory?.items??[]).some((i)=>/potion-of-healing/.test(i.definitionId)),{timeout:20_000,timeoutMsg:"Host inventory projection did not show the potion"});
    const acBefore=ent(await tomState(host),kael.id).ac;
    const shield=await playerAct(p1,sera.id,(a)=>a.spellId==="dnd.srd521.spell.shield-of-faith"&&a.available,[kael.id],null,host,"세라 신앙의 방패 → 카엘");
    await expectConverged(peers,shield.resolutionId,"장면1 신앙의 방패");
    const shielded=await everyPeerEntity(peers,kael.id,(e)=>e.ac===acBefore+2,`카엘 AC ${acBefore+2} under 신앙의 방패`);
    const conc1=await hostConcentration(host);assert.ok(conc1?.concentration?.[sera.id],`Host holds 세라's concentration; got ${JSON.stringify(conc1)}`);
    const help=await playerAct(p2,kael.id,(a)=>a.id==="action.standard.help"&&a.available,[sera.id],null,host,"카엘 도움 → 세라");
    await expectConverged(peers,help.resolutionId,"장면1 도움");
    // 틀린 플레이: 세라가 적 대상 주문을 자기 자신에게 → "그 대상에게는 사용할 수 없습니다."
    const selfTarget=await expectRefused(p1,host,sera.id,(a)=>a.spellId==="dnd.srd521.spell.sacred-flame",[sera.id],"장면1 신성한 불길 → 세라 자신",{code:"action-rejected",message:"그 대상에게는 사용할 수 없습니다."});
    await evidenceAll(peers,"tom2-01-village");
    record("장면1-마을",{potion:potionQuantity(await peerState(p2)),shield,shielded,help,selfTarget});

    // 장면 2 · 무너진 계단 — 좀비 ×2, 해골 ×1; 넘어짐; 붙잡기; 행동 소진; 인도로 집중 교체; 집중 판정; 준비 행동; 서술 피해; 쓰러짐; 죽음 내성; 안정화; 일어남; 물약.
    const zombies=await addSrdMonstersViaUi(host,"좀비","좀비",2);assert.equal(zombies.length,2);
    const [skeleton]=await addSrdMonstersViaUi(host,"해골","해골",1);
    await rawCall(host,`await mockAdapter.setCreatureStatus(args.id,"넘어짐",true);`,{id:zombies[0]});
    await everyPeerEntity(peers,zombies[0],(e)=>e.status.some((status)=>status.includes("넘어짐")),"좀비 1 넘어짐 on every peer");
    // 틀린 플레이: 단일 대상 주문에 좀비 둘 → "대상은 최대 1명입니다."
    const crowd=await expectRefused(p1,host,sera.id,(a)=>a.spellId==="dnd.srd521.spell.sacred-flame",[zombies[0],zombies[1]],"장면2 신성한 불길 → 좀비 둘",{code:"action-rejected",messagePattern:/최대 1명/});
    await expectTomParity(peers,"장면2 준비");
    await clickInitiative(host,"이니셔티브 시작");
    await waitTom(host,(s)=>s.mode==="initiative","Initiative on the Host");
    await expectTomParity(peers,"장면2 이니셔티브");
    // 카엘의 턴 — 붙잡기(해골의 내성 실패), 그리고 대검은 행동 소진 거부.
    await walkToActor(host,kael.id);
    await waitTom(p2,(s)=>s.currentActorId===kael.id,"P2 seeing 카엘's turn");
    const grapple=await playerAct(p2,kael.id,(a)=>a.id==="action.unarmed-strike.grapple"&&a.available,[skeleton],3,host,"카엘 붙잡기 → 해골");
    await expectConverged(peers,grapple.resolutionId,"장면2 붙잡기");
    const grappled=await everyPeerEntity(peers,skeleton,(e)=>e.status.some((status)=>status.includes("붙잡힘")),"해골 붙잡힘 on every peer");
    await closeResultCard(host);
    await waitProjected(p2,kael.id,isAttack("대검"),(a)=>a.available===false,"대검 unavailable after the grapple used the action");
    const spent=await expectRefused(p2,host,kael.id,isAttack("대검"),[skeleton],"장면2 카엘 대검 (행동 소진)",{code:"action-disabled",message:"행동을 이미 사용했습니다.",projectedUnavailable:true});
    await evidenceAll(peers,"tom2-02a-grapple");
    // 세라의 턴 — 인도(집중)로 신앙의 방패 집중이 끝난다; 같은 턴 상처 치료는 거부.
    await walkToActor(host,sera.id);
    await waitTom(p1,(s)=>s.currentActorId===sera.id,"P1 seeing 세라's turn");
    const guidance=await playerAct(p1,sera.id,(a)=>a.spellId==="dnd.srd521.spell.guidance"&&a.available,[kael.id],null,host,"세라 인도 → 카엘");
    await expectConverged(peers,guidance.resolutionId,"장면2 인도");
    const unshielded=await everyPeerEntity(peers,kael.id,(e)=>e.ac===acBefore,`카엘 AC back to ${acBefore} once 신앙의 방패 ended`);
    await closeResultCard(host);
    // 인도 costs the action in this SRD 5.2.1 content: every other action tile of 세라 must now read spent, and 상처 치료 is refused.
    await waitProjected(p1,sera.id,(a)=>a.spellId==="dnd.srd521.spell.cure-wounds",(a)=>a.available===false,"상처 치료 unavailable after 인도 spent the action");
    const cureRefused=await expectRefused(p1,host,sera.id,(a)=>a.spellId==="dnd.srd521.spell.cure-wounds",[kael.id],"장면2 세라 상처 치료 (행동 소진)",{code:"action-disabled",projectedUnavailable:true});
    // 좀비 1의 턴 — 세라를 후려친다; 명중이면 세라만 집중 판정을 받고, 3을 굴려 실패한다.
    await walkToActor(host,zombies[0]);
    const slam=await findAction(host,zombies[0],(a)=>a.resolutionKind==="attack","좀비 공격");
    await hostCall(host,`await mockAdapter.selectDmActor(args.id);await mockAdapter.setQueuedD20(19);await mockAdapter.resolveAction(args.actionId,[args.targetId]);`,{id:zombies[0],actionId:slam.id,targetId:sera.id});
    let hostRes=await waitHostResolutionFor(host,zombies[0]);
    // The hit walks roll → attack-result → damage-animation before the concentration save stage opens; give the presentation its time.
    const concHost=await hostAdvanceUntil(host,hostRes.resolution.id,(r)=>r.stage==="save-animation"&&Boolean(r.concentrationSave),60_000);
    assert.ok(concHost.resolution?.concentrationSave,`the hit must request a concentration save on the Host; got ${JSON.stringify(concHost.resolution)}`);
    await p1.browser.waitUntil(async()=>Boolean((await peerState(p1)).resolution?.concentrationSave),{timeout:15_000,timeoutMsg:"세라 did not receive the private concentration save"});
    assert.equal((await peerState(p2)).resolution?.concentrationSave??null,null,"카엘 must not receive 세라's private concentration save");
    await peerCall(p1,`await mockAdapter.submitConcentrationSaveD20(3);`);
    await host.browser.waitUntil(async()=>{const s=await peerState(host);return s.resolution?.id===hostRes.resolution.id&&s.resolution.concentrationSave?.natural===3;},{timeout:15_000,timeoutMsg:"Host did not receive 세라's concentration d20"});
    const slamDone=await hostAdvanceToComplete(host,hostRes.resolution.id);assert.equal(slamDone.resolution?.stage,"complete",JSON.stringify(slamDone.resolution));
    await expectConverged(peers,slamDone.resolution.id,"장면2 좀비 후려치기");
    const conc2=await hostConcentration(host);assert.equal(conc2?.concentration?.[sera.id]??null,null,`a failed save ends 인도; got ${JSON.stringify(conc2?.concentration)}`);
    await closeResultCard(host);
    await evidenceAll(peers,"tom2-02b-concentration");
    // 카엘의 턴 — 준비 행동: 해골이 다가오면 대검. 해골의 턴에 반응으로 발사.
    await walkToActor(host,kael.id);
    const greatsword=await findAction(p2,kael.id,isAttack("대검"),"대검");
    await peerCall(p2,`await mockAdapter.configureReadyAction({actorId:args.actorId,actionId:args.actionId,trigger:args.trigger});`,{actorId:kael.id,actionId:greatsword.id,trigger:"해골이 다가오면"});
    hostRes=await waitHostResolutionFor(host,kael.id);const armed=await hostAdvanceToComplete(host,hostRes.resolution.id);assert.equal(armed.resolution?.stage,"complete",JSON.stringify(armed.resolution));
    // Arming Ready is broadcast as a ready-action event ("원격 준비 행동 설정"), not as a resolution: every peer shows 카엘's 준비 행동 chip.
    for(const p of peers)await waitEntity(p,kael.id,(e)=>e.status.some((status)=>status.includes("준비 행동")),"카엘 준비 행동 chip");
    const hostReady=await readyConfigurations(host);assert.ok(hostReady.some((c)=>c.actorId===kael.id&&c.actionId===greatsword.id),`Host holds the Ready configuration; got ${JSON.stringify(hostReady)}`);
    await closeResultCard(host);
    await walkToActor(host,skeleton);
    const trigger=await findAction(p2,kael.id,(a)=>a.readyActionRole==="trigger"&&a.available,"ready trigger");
    await hostCall(host,`await mockAdapter.setQueuedD20(15);`);
    const fired=await clientAct(p2,trigger.id,[skeleton]);assert.equal(fired.ok,true,fired.error);
    hostRes=await waitHostResolutionFor(host,kael.id);const firedDone=await hostAdvanceToComplete(host,hostRes.resolution.id);assert.equal(firedDone.resolution?.stage,"complete",JSON.stringify(firedDone.resolution));
    await expectConverged(peers,firedDone.resolution.id,"장면2 준비한 대검 (반응)");
    assert.deepEqual((await readyConfigurations(host)).filter((c)=>c.actorId===kael.id),[],"Host clears the Ready configuration once the trigger fires");
    await closeResultCard(host);
    await evidenceAll(peers,"tom2-02c-ready");
    // DM의 서술 피해 — 절반, 그리고 -5; 이어 좀비 2가 카엘을 쓰러뜨린다.
    const kaelFull=ent(await tomState(host),kael.id).hp;
    await hostCall(host,`await mockAdapter.applyNarrativeDamage(args.id,"half");`,{id:kael.id});
    const halved=await everyPeerEntity(peers,kael.id,(e)=>e.hp<kaelFull&&e.hp>0,"카엘 at half HP on every peer");
    await hostCall(host,`await mockAdapter.applyNarrativeDamage(args.id,-5);`,{id:kael.id});
    const healedBack=await everyPeerEntity(peers,kael.id,(e)=>e.hp===Math.min(kaelFull,halved[host.label].hp+5),"카엘 +5 on every peer");
    await hostCall(host,`await mockAdapter.applyNarrativeDamage(args.id,999);`,{id:kael.id});
    await everyPeerEntity(peers,kael.id,(e)=>e.hp===0,"카엘 down on every peer");
    // 카엘의 턴 — 무기 타일은 잠기고 죽음 내성 굴림만 남는다.
    await walkToActor(host,kael.id);
    await waitTom(p2,(s)=>s.currentActorId===kael.id,"P2 seeing 카엘's turn while down");
    const lockedSword=await waitProjected(p2,kael.id,isAttack("대검"),(a)=>a.available===false,"대검 locked while down");
    assert.equal(lockedSword.disabledReason,"의식불명 · 죽음 내성 굴림만 할 수 있습니다.");
    const deathSave=await playerAct(p2,kael.id,(a)=>a.id==="action.death-save"&&a.available,[kael.id],12,host,"카엘 죽음 내성 굴림");
    await expectConverged(peers,deathSave.resolutionId,"장면2 죽음 내성");
    await closeResultCard(host);
    await evidenceAll(peers,"tom2-02d-death-save");
    // 막간 · 되돌리기 — DM이 방금의 죽음 내성 굴림을 되돌린다: 보상 이벤트가 모든 창에 도착하고 원 기록은 남는다.
    const undoTarget=deathSave.resolutionId;const cursorBeforeUndo=(await peerState(host)).cursor;
    await hostCall(host,`await mockAdapter.undoLastResolution();`);
    const undoHost=await peerState(host);assert.ok(undoHost.cursor>cursorBeforeUndo,`undo commits a compensating event; refusal=${JSON.stringify(undoHost.refusal)}`);
    for(const p of [p1,p2]){const s=await waitCursor(p,undoHost.cursor);assert.ok(s.activity.some((e)=>e.id===undoTarget),`${p.label} keeps the original entry in history`);assert.ok(s.activity.some((e)=>/되돌/.test(e.title)),`${p.label} records the undo`);}
    await evidenceAll(peers,"tom2-02d2-undo");
    record("막간-되돌리기",{undoTarget,cursor:[cursorBeforeUndo,undoHost.cursor]});
    // 세라의 턴 — 안정화(의학 판정), 다음 턴 상처 치료로 일어남.
    await walkToActor(host,sera.id);
    // 안정화 is a targeted 의학 check against a fixed DC 10: the downed character is the target.
    const stabilize=await playerAct(p1,sera.id,(a)=>a.id==="action.standard.stabilize"&&a.available,[kael.id],15,host,"세라 안정화 → 카엘");
    await expectConverged(peers,stabilize.resolutionId,"장면2 안정화");
    await closeResultCard(host);
    await walkToActor(host,sera.id);
    const cure=await playerAct(p1,sera.id,(a)=>a.spellId==="dnd.srd521.spell.cure-wounds"&&a.available,[kael.id],null,host,"세라 상처 치료 → 카엘");
    await expectConverged(peers,cure.resolutionId,"장면2 상처 치료");
    const revived=await everyPeerEntity(peers,kael.id,(e)=>e.hp>0,"카엘 back up on every peer");
    await closeResultCard(host);
    // 카엘의 턴 — 치유 물약.
    await walkToActor(host,kael.id);
    const potionBefore=potionQuantity(await peerState(p2));const hpBeforePotion=ent(await tomState(host),kael.id).hp;
    const potion=await playerAct(p2,kael.id,(a)=>a.id==="action.healing-potion"&&a.available,[kael.id],null,host,"카엘 치유 물약");
    await expectConverged(peers,potion.resolutionId,"장면2 물약");
    await p2.browser.waitUntil(async()=>potionQuantity(await peerState(p2))===potionBefore-1,{timeout:15_000,timeoutMsg:"카엘's potion quantity did not decrement exactly once"});
    const afterPotion=ent(await tomState(host),kael.id).hp;assert.ok(afterPotion>=hpBeforePotion,`the potion must not lower HP (${hpBeforePotion} → ${afterPotion})`);
    await closeResultCard(host);
    await clickInitiative(host,"이니셔티브 종료");
    await waitTom(host,(s)=>s.mode==="freeform","freeform on the Host");
    await expectTomParity(peers,"장면2 정리");
    await evidenceAll(peers,"tom2-02e-stairs-end");
    record("장면2-계단",{crowd,grapple,grappled,spent,guidance,unshielded,cureRefused,slam:{id:slamDone.resolution.id,save:slamDone.resolution.concentrationSave},ready:{armed:armed.resolution.id,fired:firedDone.resolution.id},narrative:{full:kaelFull,halved:halved[host.label].hp,healedBack:healedBack[host.label].hp},deathSave,stabilize,cure,revived,potion:{before:potionBefore,after:potionQuantity(await peerState(p2)),hp:[hpBeforePotion,afterPotion]}});

    // 장면 3 · 종루 — 홉고블린; 슬롯 소진 거부; 남의 턴 거부; 투창; XP; 종료.
    const [hob]=await addSrdMonstersViaUi(host,"홉고블린","홉고블린",1);
    await expectTomParity(peers,"장면3 종루");
    await clickInitiative(host,"이니셔티브 시작");
    await waitTom(host,(s)=>s.mode==="initiative","Initiative at the belfry");
    await walkToActor(host,sera.id);
    await waitTom(p1,(s)=>s.currentActorId===sera.id,"P1 seeing 세라's turn");
    const slots=await hostSlots(host,sera.id);
    const level1=slots.find((l)=>l.level===1);assert.ok(level1,`세라 has level-1 slots; got ${JSON.stringify(slots)}`);
    let slotRefusal=null;
    if(level1.current===0){slotRefusal=await expectRefused(p1,host,sera.id,(a)=>a.spellId==="dnd.srd521.spell.guiding-bolt",[hob],"장면3 유도 화살 (슬롯 소진)",{code:"action-disabled",projectedUnavailable:true});}
    else{log(`세라 still has ${level1.current} level-1 slot(s); the slot-exhaustion refusal is skipped`);}
    const flame=await playerAct(p1,sera.id,(a)=>a.spellId==="dnd.srd521.spell.sacred-flame"&&a.available,[hob],11,host,"세라 신성한 불길 → 홉고블린");
    await expectConverged(peers,flame.resolutionId,"장면3 신성한 불길");
    await closeResultCard(host);
    const offTurn=await expectRefused(p2,host,kael.id,isAttack("투창"),[hob],"장면3 카엘 투창 (세라의 턴)",{code:"action-off-turn",message:"현재 Actor의 턴이 아닙니다."});
    await walkToActor(host,kael.id);
    const javelin=await playerAct(p2,kael.id,(a)=>a.available&&isAttack("투창")(a),[hob],15,host,"카엘 투창 → 홉고블린");
    await expectConverged(peers,javelin.resolutionId,"장면3 투창");
    await closeResultCard(host);
    await clickInitiative(host,"이니셔티브 종료");
    await waitTom(host,(s)=>s.mode==="freeform","freeform after the belfry");
    const rosterIds=(await tomState(host)).campaign.roster.filter((m)=>m.characterId).map((m)=>m.id);
    await rawCall(host,`await mockAdapter.grantCampaignAdvancement(args.id,{rosterMemberIds:args.members,kind:"xp",amount:100});`,{id:campaignId,members:rosterIds});
    const xp=await waitTom(p2,(s)=>(s.campaign?.roster??[]).some((m)=>m.characterId===kael.id&&m.xp>=100),"카엘 seeing 100 XP",20_000);
    await evidenceAll(peers,"tom2-04-belfry");
    record("장면3-종루",{slots,slotRefusal,flame,offTurn,javelin,xp:xp.campaign.roster.map((m)=>({label:m.label,xp:m.xp}))});

    // 마무리 — 세션 종료.
    await click(host.browser,exactButton("← 제품"),"Host ← 제품");await click(host.browser,navButton("세션"),"Host 세션 메뉴");
    const endButton=await host.browser.$("//button[contains(@class,'danger-action') and normalize-space(.)='세션 종료']");await endButton.waitForDisplayed({timeout:10_000});await endButton.click();
    await waitTom(host,(s)=>s.role!=="host","the Host offline",30_000);
    for(const p of [p1,p2])await waitTom(p,(s)=>s.role==="offline"||s.connectionState==="disconnected",`${p.label} offline`,40_000);
    const history=await rawCall(host,`const s=await mockAdapter.getSnapshot();const c=(s.campaigns??[]).find((x)=>x.campaignId===args.id);return (c?.sessionHistory??[]).map((h)=>({title:h.title,participants:h.participantLabels}));`,{id:campaignId});
    assert.equal(history.length,1,`one session summary; got ${JSON.stringify(history)}`);
    await evidenceAll(peers,"tom2-05-ended");
    record("마무리",{history});
  }catch(error){await evidenceAll(peers,"tom2-failure");const diag={};for(const p of peers)diag[p.label]=await bounded(peerState(p).then((s)=>({refusal:s.refusal,resolution:s.resolution&&{id:s.resolution.id,stage:s.resolution.stage,actionName:s.resolution.actionName},compat:s.compatibilityMessage,activity:s.activity.slice(0,5).map((e)=>e.title),entities:s.entities.map((e)=>`${e.name}:${e.hp}/${e.maxHp}[${e.status.join(",")}]`)})).catch((e)=>({error:String(e)})),8_000,"state");await writeFile(path.join(artifactRoot,"tom2-failure-state.json"),`${JSON.stringify({beats,diag},null,2)}\n`,"utf8");throw error;}
  const evidence={gate:"S1-04",scenario:"무너진 종탑",status:"PASS",verificationSha,windowsTauri:true,topology:{host:"DM Host (no character)",clients:["P1 세라 (클레릭)","P2 카엘 (파이터)"],sessionPort,campaignId},beats};
  await writeFile(path.join(artifactRoot,"tom2-summary.json"),`${JSON.stringify(evidence,null,2)}\n`,"utf8");log(`PASS evidence: ${path.join(artifactRoot,'tom2-summary.json')}`);
}

async function cleanup(){if(keepOpen){log(`--keep-open active. Evidence: ${artifactRoot}`);return;}for(const browser of [...browsers].reverse()){try{await browser.deleteSession();}catch{}}for(const child of [...children].reverse()){if(child.exitCode===null&&!child.killed){try{child.kill();}catch{}}}if(viteStarted)log("Vite process stopped with tracked child cleanup.");}

let exitCode=0;try{await runScenario();}catch(error){exitCode=1;console.error(error instanceof Error?error.stack??error.message:error);try{await writeFile(path.join(artifactRoot,"tom2-failure.txt"),`${String(error instanceof Error?error.stack??error.message:error)}\n`,"utf8");}catch{}}finally{await cleanup();}process.exitCode=exitCode;
